const raw = $input.first().json;
const b = raw.body && Object.keys(raw.body).length ? raw.body : raw;
const topicId = String(b.topic_id ?? b.topicId ?? '').trim();
const draftId = String(b.draft_id ?? b.draftId ?? '').trim();
const esc = s => String(s).replace(/'/g, "''");
const sub = draftId
  ? 'SELECT id FROM drafts WHERE id = ' + draftId
  : 'SELECT id FROM drafts WHERE topic_id = \'' + esc(topicId) + '\' ORDER BY id DESC LIMIT 1';
const sql = 'SELECT d.id, d.topic_id, t.title, d.outline, d.body_md FROM (SELECT 1) z LEFT JOIN drafts d ON d.id = (' + sub + ') LEFT JOIN topics t ON t.topic_id = d.topic_id';
return [{ json: { topic_id: topicId, draft_id: draftId, sql } }];

const d = $('取成稿').first().json;
const srcs = $input.all().map(i => i.json);
const mat = srcs.map((s, i) => '【原文' + (i + 1) + '】' + (s.title || s.url) + '\n' + String(s.content ?? '').slice(0, 8000)).join('\n\n');
const sys = '你是事实核查编辑。对照给出的原文，逐条检查成稿中的事实性表述（数字、时间、机构、因果关系、绝对化断言）。只输出 JSON，不要解释和代码围栏。结构：{"issues":[{"claim":"成稿原句","verdict":"supported|unsupported|contradicted","evidence":"原文依据","suggestion":"修改建议"}],"risk_level":"low|medium|high","summary":"一句话结论"}。若无可疑处，issues 为空数组。最多列 8 条，每条 claim / evidence / suggestion 控制在 60 字以内；必须输出完整闭合的 JSON，不要截断。';
const user = '成稿正文：\n' + String(d.body_md ?? '').slice(0, 12000) + '\n\n参考原文：\n' + mat;
const key = $('取密钥').first().json.value || '';
const model = $('取密钥').first().json.model || 'glm-4-flash';
return [{ json: { api_key: key, model, request: { model, temperature: 0.2, max_tokens: 4096, messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] } } }];

const resp = $input.first().json;
const d = $('取成稿').first().json;
const raw = (resp && resp.choices && resp.choices[0] && resp.choices[0].message) ? String(resp.choices[0].message.content) : '';
function parseObj(text) {
  const s = String(text).replace(/```json/g, '').replace(/```/g, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {}
    // 输出被截断时，逐个补全未闭合的结构再试
    let cut = s.slice(a, b + 1);
    for (let n = 0; n < 6; n++) {
      cut = cut.replace(/,\s*$/, '') + '}';
      try { return JSON.parse(cut); } catch (e) {}
    }
  }
  return null;
}
let obj = { issues: [], risk_level: 'unknown', summary: '核查未返回结果（Key 未配置或调用失败）' };
if (raw) {
  const p = parseObj(raw);
  if (p && typeof p === 'object') {
    obj = { issues: Array.isArray(p.issues) ? p.issues : [], risk_level: p.risk_level || 'unknown', summary: p.summary || '' };
  } else {
    obj = { issues: [], risk_level: 'unknown', summary: '核查返回无法解析：' + raw.slice(0, 200) };
  }
}
return [{ json: { topic_id: d.topic_id, draft_id: d.id, title: d.title || '', body_md: d.body_md || '', facts: obj, risk_level: obj.risk_level, issue_count: obj.issues.length } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = s => { let t = esc(s); t = t.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>'); t = t.replace(/`([^`]+)`/g, '<code style="background:#f5f5f5;padding:2px 4px;border-radius:3px">$1</code>'); return t; };
const P = 'margin:0 0 18px;line-height:1.75;font-size:16px;color:#333';
function md2html(md) {
  const lines = String(md ?? '').split('\n');
  const out = []; let inList = false;
  for (let rawLine of lines) {
    const l = rawLine.trim();
    if (!l) { if (inList) { out.push('</ul>'); inList = false; } continue; }
    const h = l.match(/^(#{1,4})\s+(.*)$/);
    if (h) {
      if (inList) { out.push('</ul>'); inList = false; }
      const lv = Math.min(h[1].length, 4);
      const size = [24, 20, 18, 16][lv - 1];
      out.push('<h' + lv + ' style="margin:28px 0 14px;font-size:' + size + 'px;line-height:1.4;color:#1a1a1a;font-weight:600">' + inline(h[2]) + '</h' + lv + '>');
      continue;
    }
    if (/^[-*]\s+/.test(l)) {
      if (!inList) { out.push('<ul style="margin:0 0 18px;padding-left:22px">'); inList = true; }
      out.push('<li style="' + P + '">' + inline(l.replace(/^[-*]\s+/, '')) + '</li>');
      continue;
    }
    if (inList) { out.push('</ul>'); inList = false; }
    if (/^>\s?/.test(l)) {
      out.push('<blockquote style="margin:0 0 18px;padding:10px 14px;background:#f7f7f7;border-left:3px solid #ddd;color:#555;font-size:15px">' + inline(l.replace(/^>\s?/, '')) + '</blockquote>');
      continue;
    }
    out.push('<p style="' + P + '">' + inline(l) + '</p>');
  }
  if (inList) out.push('</ul>');
  return out.join('\n');
}
const d = $input.first().json;
const html = md2html(d.body_md);
const issues = d.facts.issues || [];
const hard = issues.filter(i => i.verdict === 'contradicted' || i.verdict === 'unsupported').length;
let decision = 'approved', draftStatus = 'approved';
if (d.risk_level === 'unknown' || d.risk_level === 'high' || hard > 0) { decision = 'needs_review'; draftStatus = 'review'; }
const sq = s => String(s ?? '').replace(/'/g, "''");
return [{ json: {
  topic_id: d.topic_id, draft_id: d.draft_id, title: d.title,
  body_md_s: sq(d.body_md), body_html_s: sq(html), title_s: sq(d.title),
  facts_s: sq(JSON.stringify(d.facts)),
  risk_s: sq(JSON.stringify({ level: d.risk_level, hard_issues: hard, issues })),
  decision, draft_status: draftStatus,
  html_len: html.length, issue_count: issues.length, hard_issues: hard,
  summary: d.facts.summary || ''
} }];
